// Loaders and helpers for the static PokeAPI snapshots in /public/data
// (generated by scripts/build-data-snapshot.mjs). Each file is fetched once per session
// and shared by every page, so navigating between pages never refetches them.
import { getBasePath } from "../utils/url.js";

const POKEAPI_BASE = "https://pokeapi.co/api/v2";
const jsonCache = new Map();

const GENERATION_NUMBER_BY_NAME = new Map([
  ["generation-i", 1],
  ["generation-ii", 2],
  ["generation-iii", 3],
  ["generation-iv", 4],
  ["generation-v", 5],
  ["generation-vi", 6],
  ["generation-vii", 7],
  ["generation-viii", 8],
  ["generation-ix", 9],
]);

const loadJson = (fileName) => {
  if (!jsonCache.has(fileName)) {
    const promise = fetch(`${getBasePath()}data/${fileName}`)
      .then((response) => {
        if (!response.ok) throw new Error(`Failed to load ${fileName}: ${response.status}`);
        return response.json();
      })
      .catch((error) => {
        // Allow a retry on the next call instead of caching the failure forever.
        jsonCache.delete(fileName);
        throw error;
      });
    jsonCache.set(fileName, promise);
  }
  return jsonCache.get(fileName);
};

export const pokemonApiUrl = (id) => `${POKEAPI_BASE}/pokemon/${id}/`;

/* ---------------------------------------------------------------- Pokémon index */

let pokemonListPromise = null;

/**
 * Every Pokémon and form as `{ name, url, id, speciesId, types, pastTypes }`.
 * Falls back to the live PokeAPI list (without types) if the snapshot can't be loaded.
 */
export const loadPokemonList = () => {
  if (!pokemonListPromise) {
    pokemonListPromise = loadJson("pokemon-index.json")
      .then((index) =>
        (index.pokemon || []).map((record) => ({
          name: record.n,
          url: pokemonApiUrl(record.i),
          id: record.i,
          speciesId: record.s ?? null,
          types: record.t || [],
          pastTypes: record.p || null,
          // Version group an alternate form first appeared in (forms with id >= 10000 only)
          introducedIn: record.v || null,
        }))
      )
      .catch(async () => {
        const response = await fetch(`${POKEAPI_BASE}/pokemon?limit=100000&offset=0`);
        const data = await response.json();
        return (data.results || []).map((entry) => ({ name: entry.name, url: entry.url }));
      })
      .catch((error) => {
        pokemonListPromise = null;
        throw error;
      });
  }
  return pokemonListPromise;
};

/**
 * Types a Pokémon had in a given generation. `pastTypes` is `[[lastGeneration, types], ...]`
 * (oldest first), e.g. Clefairy `[[5, ["normal"]]]` = Normal through Gen 5, Fairy from Gen 6.
 */
export const getTypesForGeneration = (types, pastTypes, generation) => {
  if (generation == null || !Array.isArray(pastTypes) || pastTypes.length === 0) return types || [];
  const match = pastTypes.find(([lastGeneration]) => lastGeneration >= generation);
  return match ? match[1] : types || [];
};

/** Same as getTypesForGeneration, for a raw PokeAPI `/pokemon/{id}` response. */
export const getDetailTypesForGeneration = (details, generation) => {
  const current = (details?.types || [])
    .slice()
    .sort((a, b) => a.slot - b.slot)
    .map((entry) => entry?.type?.name)
    .filter(Boolean);
  const past = (details?.past_types || [])
    .map((entry) => [
      GENERATION_NUMBER_BY_NAME.get(entry?.generation?.name),
      (entry?.types || [])
        .slice()
        .sort((a, b) => a.slot - b.slot)
        .map((t) => t?.type?.name)
        .filter(Boolean),
    ])
    .filter(([gen, types]) => gen != null && types.length > 0)
    .sort((a, b) => a[0] - b[0]);
  return getTypesForGeneration(current, past, generation);
};

/* ---------------------------------------------------------------- Pokédexes */

/** `{ [pokedexApiName]: Map<speciesId, entryNumber> }` */
let pokedexPromise = null;
export const loadPokedexMaps = () => {
  if (!pokedexPromise) {
    pokedexPromise = loadJson("pokedexes.json")
      .then((raw) => {
        const maps = {};
        for (const [name, dex] of Object.entries(raw || {})) {
          const map = new Map();
          if (Array.isArray(dex.species)) {
            dex.species.forEach((speciesId, index) => map.set(speciesId, (dex.start ?? 1) + index));
          } else if (Array.isArray(dex.entries)) {
            dex.entries.forEach(([number, speciesId]) => {
              if (!map.has(speciesId)) map.set(speciesId, number);
            });
          }
          maps[name] = map;
        }
        return maps;
      })
      .catch((error) => {
        pokedexPromise = null;
        throw error;
      });
  }
  return pokedexPromise;
};

/* ---------------------------------------------------------------- Type chart */

export const loadTypeChart = () => loadJson("type-chart.json");

/** The chart in effect for a generation (`null` = latest). */
export const getTypeChartForGeneration = (typeChart, generation) => {
  const ranges = typeChart?.ranges || [];
  if (ranges.length === 0) return null;
  if (generation == null) return ranges[ranges.length - 1];
  return (
    ranges.find((range) => generation >= range.from && (range.to == null || generation <= range.to)) ||
    ranges[ranges.length - 1]
  );
};

/** Defensive multipliers for a type combination: `{ weaknesses, resistances }` sorted for display. */
export const computeDefensiveMatchups = (chartRange, defendingTypes) => {
  const weaknesses = [];
  const resistances = [];
  if (!chartRange || !Array.isArray(defendingTypes) || defendingTypes.length === 0) {
    return { weaknesses, resistances };
  }
  for (const attacker of chartRange.types) {
    const row = chartRange.chart[attacker] || {};
    let mult = 1;
    for (const defender of defendingTypes) {
      const factor = row[defender];
      if (factor != null) mult *= factor;
    }
    if (mult > 1) weaknesses.push({ type: attacker, mult });
    else if (mult < 1) resistances.push({ type: attacker, mult });
  }
  weaknesses.sort((a, b) => b.mult - a.mult || a.type.localeCompare(b.type));
  resistances.sort((a, b) => a.mult - b.mult || a.type.localeCompare(b.type));
  return { weaknesses, resistances };
};

/* ---------------------------------------------------------------- Moves */

/**
 * `{ versionGroups: { [name]: { order, generation } }, moves: { [name]: { t, p, a, pp, pr, c, g, h? } } }`
 * t=type, p=power, a=accuracy, pp, pr=priority, c=damage class, g=generation introduced,
 * h=history `[{ vg, t?, p?, a?, pp? }]` (values in effect *before* that version group). Use
 * getMoveForVersionGroup() rather than reading `h` directly.
 */
export const loadMoveData = () => loadJson("moves.json");

/** `{ [moveName]: "Has a 10% chance to burn the target." }` (short English effect text) */
export const loadMoveEffects = () => loadJson("move-effects.json");

/**
 * `{ abilities: [{ n: name, g: generation, e: shortEffect, p: [[pokemonId, isHidden 0|1], ...] }] }`
 * (main-series abilities only). Pokémon ids match pokemon-index.json / loadPokemonList().
 */
export const loadAbilityData = () => loadJson("abilities.json");

// Before Gen 4 a damaging move's category came from its type, not the move itself.
const SPECIAL_TYPES_BEFORE_GEN_4 = new Set(["fire", "water", "grass", "electric", "ice", "psychic", "dragon", "dark"]);

/**
 * Move stats as they were in a version group (`null` = current values).
 * PokeAPI's change log stores the values that applied *before* each listed version group.
 */
export const getMoveForVersionGroup = (moveData, moveName, versionGroup = null) => {
  const move = moveData?.moves?.[moveName];
  if (!move) return null;
  const groups = moveData.versionGroups || {};
  const target = versionGroup ? groups[versionGroup] : null;
  let type = move.t;
  let power = move.p;
  let accuracy = move.a;
  let pp = move.pp;
  if (target && Array.isArray(move.h)) {
    const resolved = {};
    for (const change of move.h) {
      const order = groups[change.vg]?.order;
      if (order == null || order <= target.order) continue;
      for (const key of ["t", "p", "a", "pp"]) {
        if (change[key] !== undefined && resolved[key] === undefined) resolved[key] = change[key];
      }
    }
    if (resolved.t !== undefined) type = resolved.t;
    if (resolved.p !== undefined) power = resolved.p;
    if (resolved.a !== undefined) accuracy = resolved.a;
    if (resolved.pp !== undefined) pp = resolved.pp;
  }
  let damageClass = move.c;
  const generation = target?.generation ?? null;
  if (generation != null && generation <= 3 && damageClass && damageClass !== "status") {
    damageClass = SPECIAL_TYPES_BEFORE_GEN_4.has(type) ? "special" : "physical";
  }
  return {
    name: moveName,
    type,
    power: power ?? null,
    accuracy: accuracy ?? null,
    pp: pp ?? null,
    priority: move.pr ?? 0,
    damage_class: damageClass ?? null,
    generation: move.g ?? null,
  };
};
